import{U as e,W as t,nt as n,t as r}from"./chunks/framework.CPHJXLir.js";var i=JSON.parse(`{"title":"Operators and Expressions","description":"","frontmatter":{},"headers":[],"relativePath":"variables-data-types-operators-and-control-flow/operators-and-expressions.md","filePath":"variables-data-types-operators-and-control-flow/operators-and-expressions.md"}`),a={name:`variables-data-types-operators-and-control-flow/operators-and-expressions.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="operators-and-expressions" tabindex="-1">Operators and Expressions <a class="header-anchor" href="#operators-and-expressions" aria-label="Permalink to “Operators and Expressions”">​</a></h1><p>An <strong>operator</strong> is a symbol or keyword that performs an operation on one or more values.</p><p>An <strong>expression</strong> is a combination of values, variables, and operators that produces a result.</p><p>For example:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Total := Quantity * UnitPrice;</span></span></code></pre></div><p>Here, <code>*</code> is an operator, while <code>Quantity * UnitPrice</code> is an expression. The result is assigned to <code>Total</code> using <code>:=</code>.</p><h2 id="arithmetic-operators" tabindex="-1">Arithmetic Operators <a class="header-anchor" href="#arithmetic-operators" aria-label="Permalink to “Arithmetic Operators”">​</a></h2><p>Arithmetic operators perform mathematical calculations.</p><table tabindex="0"><thead><tr><th>Operator</th><th>Meaning</th><th>Example</th><th>Result</th></tr></thead><tbody><tr><td><code>+</code></td><td>Addition</td><td><code>10 + 3</code></td><td><code>13</code></td></tr><tr><td><code>-</code></td><td>Subtraction</td><td><code>10 - 3</code></td><td><code>7</code></td></tr><tr><td><code>*</code></td><td>Multiplication</td><td><code>10 * 3</code></td><td><code>30</code></td></tr><tr><td><code>/</code></td><td>Division</td><td><code>10 / 2</code></td><td><code>5</code></td></tr><tr><td><code>div</code></td><td>Integer division</td><td><code>10 div 3</code></td><td><code>3</code></td></tr><tr><td><code>mod</code></td><td>Remainder after division</td><td><code>10 mod 3</code></td><td><code>1</code></td></tr></tbody></table><p><strong>Important distinctions:</strong></p><ul><li><code>/</code> performs division and can produce a fractional result when used with <code>Decimal</code> values.</li><li><code>div</code> returns the integer quotient, discarding the fractional part.</li><li><code>mod</code> returns the remainder.</li></ul><p>For example, <code>10 div 3</code> returns <code>3</code>, while <code>10 mod 3</code> returns <code>1</code>.</p><p>AL also supports unary <code>+</code> and <code>-</code> operators, which indicate a number&#39;s sign:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Quantity := -5;</span></span>
<span class="line"><span>Quantity := +5;</span></span></code></pre></div><h2 id="comparison-operators" tabindex="-1">Comparison Operators <a class="header-anchor" href="#comparison-operators" aria-label="Permalink to “Comparison Operators”">​</a></h2><p>Comparison operators compare two values and produce a Boolean result: <code>true</code> or <code>false</code>.</p><table tabindex="0"><thead><tr><th>Operator</th><th>Meaning</th><th>Example</th></tr></thead><tbody><tr><td><code>=</code></td><td>Equal to</td><td><code>5 = 5</code> → <code>true</code></td></tr><tr><td><code>&lt;&gt;</code></td><td>Not equal to</td><td><code>5 &lt;&gt; 3</code> → <code>true</code></td></tr><tr><td><code>&gt;</code></td><td>Greater than</td><td><code>8 &gt; 5</code> → <code>true</code></td></tr><tr><td><code>&lt;</code></td><td>Less than</td><td><code>3 &lt; 5</code> → <code>true</code></td></tr><tr><td><code>&gt;=</code></td><td>Greater than or equal to</td><td><code>5 &gt;= 5</code> → <code>true</code></td></tr><tr><td><code>&lt;=</code></td><td>Less than or equal to</td><td><code>4 &lt;= 5</code> → <code>true</code></td></tr></tbody></table><p><strong>Important:</strong> In AL, <code>=</code> is used for equality comparisons, while <code>:=</code> is used for assignment.</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Quantity := 10;       // Assignment</span></span>
<span class="line"><span>IsAvailable := Quantity &gt; 0; // Comparison produces a Boolean</span></span></code></pre></div><h2 id="logical-operators" tabindex="-1">Logical Operators <a class="header-anchor" href="#logical-operators" aria-label="Permalink to “Logical Operators”">​</a></h2><p>Logical operators combine or reverse Boolean expressions.</p><table tabindex="0"><thead><tr><th>Operator</th><th>Meaning</th><th>Example</th><th>Result</th></tr></thead><tbody><tr><td><code>and</code></td><td>True when both conditions are true</td><td><code>5 &gt; 2 and 10 &gt; 3</code></td><td><code>true</code></td></tr><tr><td><code>or</code></td><td>True when at least one condition is true</td><td><code>5 &lt; 2 or 10 &gt; 3</code></td><td><code>true</code></td></tr><tr><td><code>not</code></td><td>Reverses a Boolean value</td><td><code>not (5 &gt; 2)</code></td><td><code>false</code></td></tr><tr><td><code>xor</code></td><td>True when exactly one condition is true</td><td><code>true xor false</code></td><td><code>true</code></td></tr></tbody></table><h3 id="truth-table" tabindex="-1">Truth table <a class="header-anchor" href="#truth-table" aria-label="Permalink to “Truth table”">​</a></h3><table tabindex="0"><thead><tr><th>A</th><th>B</th><th>A and B</th><th>A or B</th><th>A xor B</th></tr></thead><tbody><tr><td><code>true</code></td><td><code>true</code></td><td><code>true</code></td><td><code>true</code></td><td><code>false</code></td></tr><tr><td><code>true</code></td><td><code>false</code></td><td><code>false</code></td><td><code>true</code></td><td><code>true</code></td></tr><tr><td><code>false</code></td><td><code>true</code></td><td><code>false</code></td><td><code>true</code></td><td><code>true</code></td></tr><tr><td><code>false</code></td><td><code>false</code></td><td><code>false</code></td><td><code>false</code></td><td><code>false</code></td></tr></tbody></table><p><code>not</code> operates on a single Boolean value:</p><table tabindex="0"><thead><tr><th>A</th><th>not A</th></tr></thead><tbody><tr><td><code>true</code></td><td><code>false</code></td></tr><tr><td><code>false</code></td><td><code>true</code></td></tr></tbody></table><p><strong>Example:</strong></p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>namespace HelloWorld;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>using Microsoft.Sales.Customer;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>pageextension 50100 CustomerListExt extends &quot;Customer List&quot;</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    trigger OnOpenPage()</span></span>
<span class="line"><span>    var</span></span>
<span class="line"><span>        Stock: Integer;</span></span>
<span class="line"><span>        OrderAmount: Integer;</span></span>
<span class="line"><span>        IsAvailable: Boolean;</span></span>
<span class="line"><span>    begin</span></span>
<span class="line"><span>        Stock := 55;</span></span>
<span class="line"><span>        OrderAmount := 55;</span></span>
<span class="line"><span>        IsAvailable := true;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        if (Stock &gt;= OrderAmount) and IsAvailable then</span></span>
<span class="line"><span>            Message(&#39;Order can be placed&#39;)</span></span>
<span class="line"><span>        else</span></span>
<span class="line"><span>            Message(&#39;Order cannot be placed&#39;);</span></span>
<span class="line"><span>    end;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>The message appears only when both conditions are true.</p><h2 id="string-concatenation" tabindex="-1">String Concatenation <a class="header-anchor" href="#string-concatenation" aria-label="Permalink to “String Concatenation”">​</a></h2><p><strong>String concatenation</strong> means joining text values together.</p><p>In AL, the <code>+</code> operator can concatenate <code>Text</code> and <code>Code</code> values.</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>var</span></span>
<span class="line"><span>    FirstName: Text[30];</span></span>
<span class="line"><span>    LastName: Text[30];</span></span>
<span class="line"><span>    FullName: Text[60];</span></span>
<span class="line"><span>begin</span></span>
<span class="line"><span>    FirstName := &#39;John&#39;;</span></span>
<span class="line"><span>    LastName := &#39;Doe&#39;;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    FullName := FirstName + &#39; &#39; + LastName;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    Message(FullName);</span></span>
<span class="line"><span>end;</span></span></code></pre></div><p>Output:</p><p><code>John Doe</code></p><p>The <code>+</code> operator behaves differently depending on the operand types:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Total := 10 + 5;                    // Arithmetic addition: 15</span></span>
<span class="line"><span>FullName := &#39;John&#39; + &#39; Doe&#39;;   // Text concatenation</span></span></code></pre></div><p>The first expression adds numbers. The second joins text.</p><p><strong>Note:</strong> Concatenating <code>Code</code> values produces a <code>Code</code> result when both operands are <code>Code</code>. Mixing <code>Code</code> and <code>Text</code> produces a <code>Text</code> result.</p><h2 id="operator-precedence" tabindex="-1">Operator Precedence <a class="header-anchor" href="#operator-precedence" aria-label="Permalink to “Operator Precedence”">​</a></h2><p><strong>Operator precedence</strong> determines which operations are evaluated first when an expression contains multiple operators.</p><p>Consider:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Result := 2 + 3 * 4;</span></span></code></pre></div><p>The multiplication is evaluated first, so:</p><p><code>2 + (3 * 4) = 14</code></p><p>However:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Result := (2 + 3) * 4;</span></span></code></pre></div><p>Parentheses force the addition to happen first:</p><p><code>(2 + 3) * 4 = 20</code></p><h3 id="al-operator-precedence" tabindex="-1">AL operator precedence <a class="header-anchor" href="#al-operator-precedence" aria-label="Permalink to “AL operator precedence”">​</a></h3><p>The following groups are listed from higher to lower precedence:</p><table tabindex="0"><thead><tr><th>Priority</th><th>Operators</th></tr></thead><tbody><tr><td>1 — Highest</td><td><code>.</code>, <code>[ ]</code>, <code>()</code>, <code>::</code>, <code>@</code></td></tr><tr><td>2</td><td><code>not</code>, unary <code>-</code>, unary <code>+</code></td></tr><tr><td>3</td><td><code>*</code>, <code>/</code>, <code>div</code>, <code>mod</code>, <code>and</code>, <code>xor</code></td></tr><tr><td>4</td><td><code>+</code>, <code>-</code>, <code>or</code></td></tr><tr><td>5</td><td><code>&gt;</code>, <code>&gt;=</code>, <code>&lt;</code>, <code>&lt;=</code>, <code>=</code>, <code>&lt;&gt;</code>, <code>in</code></td></tr><tr><td>6 — Lowest</td><td><code>..</code> (range operator)</td></tr></tbody></table><p>For example:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Result := 10 + 5 * 2;</span></span></code></pre></div><p>The result is <code>20</code> because multiplication has higher precedence than addition.</p><p><strong>A particularly important AL detail:</strong> <code>and</code> and <code>xor</code> have higher precedence than <code>or</code>.</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Result := ConditionA or ConditionB and ConditionC;</span></span></code></pre></div><p>This is evaluated as:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Result := ConditionA or (ConditionB and ConditionC);</span></span></code></pre></div><p>Use parentheses to make complex expressions clear and avoid unintended results.</p><h2 id="boolean-expressions" tabindex="-1">Boolean Expressions <a class="header-anchor" href="#boolean-expressions" aria-label="Permalink to “Boolean Expressions”">​</a></h2><p>A <strong>Boolean expression</strong> is an expression that evaluates to either <code>true</code> or <code>false</code>.</p><p>Comparison and logical operators commonly produce Boolean expressions.</p><p>Examples:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Quantity &gt; 0</span></span></code></pre></div><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>UnitPrice &lt;= 1000</span></span></code></pre></div><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Quantity &gt; 0 and IsAvailable</span></span></code></pre></div><p>Boolean expressions are commonly used in <code>if</code> statements to control program flow.</p><h3 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to “Example”">​</a></h3><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>var</span></span>
<span class="line"><span>    Quantity: Integer;</span></span>
<span class="line"><span>    IsAvailable: Boolean;</span></span>
<span class="line"><span>begin</span></span>
<span class="line"><span>    Quantity := 10;</span></span>
<span class="line"><span>    IsAvailable := true;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    if Quantity &gt; 0 and IsAvailable then</span></span>
<span class="line"><span>        Message(&#39;The product can be sold.&#39;)</span></span>
<span class="line"><span>    else</span></span>
<span class="line"><span>        Message(&#39;The product cannot be sold.&#39;);</span></span>
<span class="line"><span>end;</span></span></code></pre></div><p>The condition <code>Quantity &gt; 0 and IsAvailable</code> evaluates to <code>true</code> because the quantity is positive and the product is available.</p><h3 id="boolean-variables-versus-boolean-expressions" tabindex="-1">Boolean variables versus Boolean expressions <a class="header-anchor" href="#boolean-variables-versus-boolean-expressions" aria-label="Permalink to “Boolean variables versus Boolean expressions”">​</a></h3><p>These concepts are related but different:</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>IsAvailable := true;</span></span></code></pre></div><p>This assigns a Boolean value to a variable.</p><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>IsAvailable := Quantity &gt; 0;</span></span></code></pre></div><p>This evaluates a Boolean expression and assigns its result to the variable.</p><h2 id="practical-example-try-operators-in-business-central" tabindex="-1">Practical Example: Try Operators in Business Central <a class="header-anchor" href="#practical-example-try-operators-in-business-central" aria-label="Permalink to “Practical Example: Try Operators in Business Central”">​</a></h2><div class="language-al"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">al</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>namespace HelloWorld;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>using Microsoft.Sales.Customer;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>pageextension 50100 CustomerListExt extends &quot;Customer List&quot;</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    trigger OnOpenPage()</span></span>
<span class="line"><span>    var</span></span>
<span class="line"><span>        Quantity: Integer;</span></span>
<span class="line"><span>        UnitPrice: Decimal;</span></span>
<span class="line"><span>        Total: Decimal;</span></span>
<span class="line"><span>        IsAvailable: Boolean;</span></span>
<span class="line"><span>        IsBulkOrder: Boolean;</span></span>
<span class="line"><span>        ProductName: Text[50];</span></span>
<span class="line"><span>        DiscountedPrice: Decimal;</span></span>
<span class="line"><span>    begin</span></span>
<span class="line"><span>        Quantity := 10;</span></span>
<span class="line"><span>        UnitPrice := 250;</span></span>
<span class="line"><span>        IsAvailable := true;</span></span>
<span class="line"><span>        ProductName := &#39;Laptop&#39;;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        // Arithmetic operators</span></span>
<span class="line"><span>        Total := Quantity * UnitPrice;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        Message(</span></span>
<span class="line"><span>            &#39;Product: %1\\Quantity: %2\\Unit price: %3\\Total: %4&#39;,</span></span>
<span class="line"><span>            ProductName,</span></span>
<span class="line"><span>            Quantity,</span></span>
<span class="line"><span>            UnitPrice,</span></span>
<span class="line"><span>            Total</span></span>
<span class="line"><span>        );</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        // Comparison and logical operators</span></span>
<span class="line"><span>        IsBulkOrder := Quantity &gt;= 10 and IsAvailable;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        if IsBulkOrder then</span></span>
<span class="line"><span>            Message(&#39;The order qualifies as an available bulk order.&#39;)</span></span>
<span class="line"><span>        else</span></span>
<span class="line"><span>            Message(&#39;The order does not qualify as an available bulk order.&#39;);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        // Operator precedence</span></span>
<span class="line"><span>        DiscountedPrice := UnitPrice - 20 * 2;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        Message(</span></span>
<span class="line"><span>            &#39;Price after discount: %1&#39;,</span></span>
<span class="line"><span>            DiscountedPrice</span></span>
<span class="line"><span>        );</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        // String concatenation</span></span>
<span class="line"><span>        Message(&#39;Product summary: &#39; + ProductName + &#39; is available.&#39;);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        // Boolean negation</span></span>
<span class="line"><span>        if not IsAvailable then</span></span>
<span class="line"><span>            Message(&#39;The product is unavailable.&#39;)</span></span>
<span class="line"><span>        else</span></span>
<span class="line"><span>            Message(&#39;The product is available.&#39;);</span></span>
<span class="line"><span>    end;</span></span>
<span class="line"><span>}</span></span></code></pre></div><h3 id="expected-results" tabindex="-1">Expected results <a class="header-anchor" href="#expected-results" aria-label="Permalink to “Expected results”">​</a></h3><ul><li><strong>Arithmetic:</strong> The total is <code>2500</code>.</li><li><strong>Boolean expression:</strong> The bulk-order condition is true because the quantity is at least 10 and the product is available.</li><li><strong>Operator precedence:</strong> The discounted price is <code>210</code>, because <code>20 * 2</code> is evaluated before the subtraction.</li><li><strong>String concatenation:</strong> The message displays <code>Product summary: Laptop is available.</code></li><li><strong>Boolean negation:</strong> Since <code>IsAvailable</code> is <code>true</code>, <code>not IsAvailable</code> is <code>false</code>, so the <code>else</code> branch runs.</li></ul><p>This example demonstrates arithmetic, comparison, logical operators, string concatenation, precedence, and Boolean expressions in one place.</p><h2 id="further-reading" tabindex="-1">Further Reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to “Further Reading”">​</a></h2><ul><li><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/devenv-al-operators" target="_blank" rel="noreferrer">AL operators — Microsoft Learn</a></li><li><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/devenv-al-arithmetic-operators" target="_blank" rel="noreferrer">Arithmetic operators — Microsoft Learn</a></li><li><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/devenv-al-boolean-operators" target="_blank" rel="noreferrer">Boolean operators — Microsoft Learn</a></li><li><a href="https://learn.microsoft.com/en-us/dynamics365/business-central/dev-itpro/developer/devenv-al-control-statements" target="_blank" rel="noreferrer">AL control statements — Microsoft Learn</a></li></ul>`,84)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};